// ─── File: PortfolioAggregatorDemo.java ───
// Runnable fork-join / scatter-gather demo with CompletableFuture.
package com.bank.portfolio;

import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.logging.*;

public class PortfolioAggregatorDemo {

    private static final Logger log = Logger.getLogger("Portfolio");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Dedicated bounded pool for blocking I/O-style child tasks.
        ExecutorService pool = Executors.newFixedThreadPool(4);
        PortfolioAggregator aggregator = new PortfolioAggregator(
                new AccountService(), new EquityService(), new FundService(), pool);

        long start = System.currentTimeMillis();
        NetWorth nw = aggregator.computeNetWorth("SAV2001");
        long elapsed = System.currentTimeMillis() - start;

        log.info(() -> "Cash   = Rs." + nw.cash());
        log.info(() -> "Equity = Rs." + nw.equity());
        log.info(() -> "Funds  = Rs." + nw.funds());
        log.info(() -> "TOTAL net worth = Rs." + nw.total()
                + " (computed in " + elapsed + "ms, parallel)");
        pool.shutdown();
    }
}

// ─── service/AccountService.java ───
class AccountService {
    BigDecimal getBalance(String accountId) {
        sleep(400);                         // simulate DB latency
        return new BigDecimal("1000000");   // Rajesh's cash
    }
    static void sleep(long ms) {
        try { Thread.sleep(ms); } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

// ─── service/EquityService.java ───
class EquityService {
    BigDecimal getHoldingsValue(String accountId) {
        AccountService.sleep(600);          // slowest child
        return new BigDecimal("450000");    // equity holdings
    }
}

// ─── service/FundService.java ───
class FundService {
    BigDecimal getFundValue(String accountId) {
        AccountService.sleep(300);
        return new BigDecimal("275000");    // mutual funds
    }
}

// ─── dto/NetWorth.java ───
record NetWorth(BigDecimal cash, BigDecimal equity, BigDecimal funds) {
    BigDecimal total() { return cash.add(equity).add(funds); }
}

// ─── aggregator/PortfolioAggregator.java (the PARENT task) ───
class PortfolioAggregator {
    private static final Logger log = Logger.getLogger("Portfolio");
    private final AccountService accountService;
    private final EquityService equityService;
    private final FundService fundService;
    private final ExecutorService pool;

    PortfolioAggregator(AccountService a, EquityService e, FundService f,
                        ExecutorService pool) {
        this.accountService = a; this.equityService = e;
        this.fundService = f; this.pool = pool;
    }

    NetWorth computeNetWorth(String accountId) {
        // ---- FORK: three independent child tasks run concurrently ----
        CompletableFuture<BigDecimal> cashF = CompletableFuture.supplyAsync(
                () -> { log.info("child: fetching cash"); 
                        return accountService.getBalance(accountId); }, pool);

        CompletableFuture<BigDecimal> equityF = CompletableFuture.supplyAsync(
                () -> { log.info("child: fetching equity");
                        return equityService.getHoldingsValue(accountId); }, pool)
                // graceful degradation: down equity service contributes zero
                .exceptionally(ex -> {
                    log.warning("equity failed, using 0: " + ex.getMessage());
                    return BigDecimal.ZERO;
                });

        CompletableFuture<BigDecimal> fundF = CompletableFuture.supplyAsync(
                () -> { log.info("child: fetching funds");
                        return fundService.getFundValue(accountId); }, pool);

        try {
            // ---- JOIN: wait for ALL children, bounded by a timeout ----
            CompletableFuture.allOf(cashF, equityF, fundF)
                    .get(2, TimeUnit.SECONDS);
            // ---- COMBINE: results are ready, join() does not block now ----
            return new NetWorth(cashF.join(), equityF.join(), fundF.join());
        } catch (TimeoutException te) {
            throw new RuntimeException("net worth timed out", te);
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(ie);
        } catch (ExecutionException ee) {
            throw new RuntimeException("net worth failed", ee.getCause());
        }
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
